import React, { useState, useRef, useEffect, useCallback } from 'react';
import axios from 'axios';

const COLORS = {
  primary: '#3B82F6',
  success: '#10B981',
  error: '#EF4444',
  gray: '#64748B',
  light: '#F8FAFC',
};

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);
  const captureIntervalRef = useRef(null);
  const audioContextRef = useRef(null);

  const [isCameraActive, setIsCameraActive] = useState(false);
  const [autoMode, setAutoMode] = useState(false);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState('idle'); // idle | scanning | success | error

  const [result, setResult] = useState(null);
  const [capturedImage, setCapturedImage] = useState(null);
  const [registeredPhotoUrl, setRegisteredPhotoUrl] = useState(null);
  const [faceBox, setFaceBox] = useState(null);

  const [frameCount, setFrameCount] = useState(0);
  const [scanAttempts, setScanAttempts] = useState(0);
  const [successCount, setSuccessCount] = useState(0);
  const [errorCount, setErrorCount] = useState(0);
  const [lastDetection, setLastDetection] = useState(null);
  const [errorMsg, setErrorMsg] = useState(null);

  // ====================== AUDIO FEEDBACK ======================
  const playSound = useCallback((type) => {
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)();
      }
      const ctx = audioContextRef.current;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      if (type === 'success') {
        osc.type = 'sine';
        osc.frequency.setValueAtTime(800, ctx.currentTime);
        setTimeout(() => osc.frequency.setValueAtTime(1200, ctx.currentTime + 0.1), 80);
        gain.gain.value = 0.28;
      } else {
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(420, ctx.currentTime);
        gain.gain.value = 0.2;
      }

      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 2200;

      osc.connect(filter);
      filter.connect(gain);
      gain.connect(ctx.destination);

      osc.start();
      setTimeout(() => {
        gain.gain.linearRampToValueAtTime(0.001, ctx.currentTime + 0.4);
        osc.stop(ctx.currentTime + 0.5);
      }, type === 'success' ? 320 : 220);
    } catch (e) {
      console.warn('Audio non disponible');
    }
  }, []);

  // ====================== DÉMARRAGE CAMÉRA ======================
  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } },
        audio: false,
      });

      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
      setIsCameraActive(true);
      console.log('✅ Caméra démarrée');
    } catch (err) {
      console.error('Erreur caméra:', err);
      setErrorMsg("Impossible d'accéder à la caméra. Vérifiez les permissions.");
      addNotification("❌ Erreur d'accès à la caméra", 'error');
    }
  };

  // ====================== ARRÊT CAMÉRA ======================
  const stopCamera = () => {
    if (captureIntervalRef.current) {
      clearInterval(captureIntervalRef.current);
      captureIntervalRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setIsCameraActive(false);
    setAutoMode(false);
    setStatus('idle');
    setFaceBox(null);
    console.log('🛑 Caméra arrêtée');
  };

  // ====================== MODE AUTO ======================
  const toggleAutoMode = async () => {
    if (!autoMode) {
      // Démarrer le mode auto
      if (!isCameraActive) {
        await startCamera();
      }
      setAutoMode(true);
      setStatus('scanning');
      setErrorMsg(null);
    } else {
      // Arrêter le mode auto
      setAutoMode(false);
      setStatus('idle');
    }
  };

  // Boucle de capture automatique
  useEffect(() => {
    if (!autoMode || !isCameraActive) {
      if (captureIntervalRef.current) {
        clearInterval(captureIntervalRef.current);
        captureIntervalRef.current = null;
      }
      return;
    }

    captureIntervalRef.current = setInterval(async () => {
      if (!videoRef.current || loading) return;

      try {
        const canvas = document.createElement('canvas');
        canvas.width = videoRef.current.videoWidth || 1280;
        canvas.height = videoRef.current.videoHeight || 720;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(videoRef.current, 0, 0);

        const imageBase64 = canvas.toDataURL('image/jpeg', 0.85);

        setLoading(true);
        setFrameCount(prev => prev + 1);
        setScanAttempts(prev => prev + 1);

        const response = await axios.post('/api/recognize/', {
          image: imageBase64.split(',')[1],
        });

        const data = response.data;

        if (data.face_box) setFaceBox(data.face_box);

        if (data.success && data.student) {
          setResult(data);
          setCapturedImage(imageBase64);
          setRegisteredPhotoUrl(data.registered_photo_url || null);
          setLastDetection(new Date().toLocaleTimeString());
          setStatus('success');
          setSuccessCount(prev => prev + 1);

          playSound('success');
          addNotification(`✅ ${data.student} marqué présent`, 'success');

          // Pause temporaire après succès
          setAutoMode(false);
          setTimeout(() => setAutoMode(true), 4500);
        } else {
          setStatus('error');
          setErrorMsg(data.message || "Visage détecté mais non reconnu");
          setErrorCount(prev => prev + 1);
          playSound('error');
        }
      } catch (err) {
        const msg = err.response?.data?.message || err.message || "Erreur de connexion au serveur";
        setErrorMsg(msg);
        setStatus('error');
        setErrorCount(prev => prev + 1);
        playSound('error');
        addNotification(`❌ ${msg}`, 'error');
      } finally {
        setLoading(false);
      }
    }, 1400); // Intervalle entre 1200ms et 1500ms → 1400ms

    return () => {
      if (captureIntervalRef.current) {
        clearInterval(captureIntervalRef.current);
      }
    };
  }, [autoMode, isCameraActive, loading, addNotification, playSound]);

  // ====================== CAPTURE MANUELLE ======================
  const handleManualCapture = async () => {
    if (!videoRef.current || loading) {
      if (!isCameraActive) {
        addNotification("Veuillez d'abord démarrer la caméra", 'warning');
      }
      return;
    }

    setLoading(true);
    setErrorMsg(null);
    setResult(null);
    setFaceBox(null);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);

      const imageBase64 = canvas.toDataURL('image/jpeg', 0.9);
      setCapturedImage(imageBase64);

      const response = await axios.post('/api/recognize/', {
        image: imageBase64.split(',')[1],
      });

      const data = response.data;

      if (data.success && data.student) {
        setResult(data);
        setRegisteredPhotoUrl(data.registered_photo_url);
        setLastDetection(new Date().toLocaleTimeString());
        setStatus('success');
        setSuccessCount(prev => prev + 1);
        playSound('success');
        addNotification(`✅ ${data.student} marqué présent`, 'success');
      } else {
        setStatus('error');
        setErrorMsg(data.message || "Visage détecté mais non reconnu");
        setErrorCount(prev => prev + 1);
        playSound('error');
      }
    } catch (err) {
      const msg = err.response?.data?.message || "Erreur lors de la reconnaissance";
      setErrorMsg(msg);
      setStatus('error');
      setErrorCount(prev => prev + 1);
      playSound('error');
      addNotification(`❌ ${msg}`, 'error');
    } finally {
      setLoading(false);
    }
  };

  // ====================== RENDER PHOTO ENREGISTRÉE ======================
  const RegisteredPhoto = () => {
    if (registeredPhotoUrl) {
      return <img src={registeredPhotoUrl} alt="Photo enregistrée" style={styles.photo} />;
    }
    return (
      <div style={styles.placeholder}>
        <div style={styles.silhouette}>👤</div>
        <p>Photo de référence</p>
      </div>
    );
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>👤 Reconnaissance Faciale - Présence</h1>

      <div style={styles.videoWrapper}>
        <div style={styles.videoContainer}>
          <video
            ref={videoRef}
            autoPlay
            playsInline
            muted
            style={styles.video}
            aria-label="Flux vidéo caméra"
          />
          <canvas ref={canvasRef} style={styles.overlayCanvas} />

          {isCameraActive && (
            <div style={{
              ...styles.statusBadge,
              backgroundColor: status === 'success' ? COLORS.success :
                              status === 'error' ? COLORS.error : '#10B981'
            }}>
              {status === 'success' ? '✅ Reconnu' :
               status === 'error' ? '❌ Échec' : '🔴 Caméra active'}
            </div>
          )}
        </div>
      </div>

      <div style={styles.actions}>
        <button
          onClick={handleManualCapture}
          disabled={loading || !isCameraActive}
          style={styles.btnPrimary}
          aria-label="Capturer maintenant"
        >
          {loading ? '⏳ Traitement...' : '📸 Capturer maintenant'}
        </button>

        <button
          onClick={toggleAutoMode}
          style={{
            ...styles.btn,
            backgroundColor: autoMode ? COLORS.error : '#22C55E'
          }}
          aria-label={autoMode ? "Arrêter le mode automatique" : "Démarrer le mode automatique"}
        >
          {autoMode ? '⏹ Arrêter Auto' : '▶️ Démarrer Auto'}
        </button>

        <button
          onClick={stopCamera}
          disabled={!isCameraActive}
          style={styles.btnDanger}
          aria-label="Fermer la caméra"
        >
          🛑 Fermer Caméra
        </button>
      </div>

      {/* Comparaison des photos */}
      {(capturedImage || result) && (
        <div style={styles.comparisonContainer}>
          <div style={styles.photoPair}>
            <div>
              <p style={styles.photoLabel}>📸 Photo capturée</p>
              {capturedImage ? (
                <img src={capturedImage} alt="Capture en direct" style={styles.photo} />
              ) : (
                <div style={styles.noCapture}>Aucune capture disponible</div>
              )}
            </div>

            <div>
              <p style={styles.photoLabel}>📁 Photo enregistrée</p>
              <RegisteredPhoto />
            </div>
          </div>
        </div>
      )}

      {/* Résultat succès */}
      {result && result.success && (
        <div style={styles.successBox}>
          <h3>✅ {result.student} marqué présent</h3>
          <p><strong>Email :</strong> {result.email || 'N/A'}</p>
          <p><strong>Confiance :</strong> {(result.confidence * 100).toFixed(1)}%</p>
          <p><strong>ID Présence :</strong> {result.attendance_id}</p>
          <p><strong>Heure :</strong> {lastDetection}</p>
        </div>
      )}

      {/* Message d'erreur */}
      {errorMsg && (
        <div style={styles.errorBox}>
          ❌ {errorMsg}
        </div>
      )}

      {/* Statistiques */}
      <div style={styles.stats}>
        <div>Dernière détection : <strong>{lastDetection || '—'}</strong></div>
        <div>Succès : <strong style={{ color: COLORS.success }}>{successCount}</strong></div>
        <div>Échecs : <strong style={{ color: COLORS.error }}>{errorCount}</strong></div>
      </div>

      {/* Debug */}
      <div style={styles.debug}>
        Caméra : {isCameraActive ? 'Active' : 'Inactive'} | 
        Mode Auto : {autoMode ? 'ON' : 'OFF'} | 
        Frames : {frameCount} | 
        Tentatives : {scanAttempts} | 
        Succès/Échecs : {successCount}/{errorCount}
      </div>
    </div>
  );
};

const styles = {
  container: { padding: '30px', maxWidth: '1100px', margin: '0 auto', fontFamily: 'system-ui, Arial, sans-serif' },
  title: { textAlign: 'center', fontSize: '1.9rem', marginBottom: '30px', color: '#1E2937' },

  videoWrapper: { position: 'relative', marginBottom: '30px' },
  videoContainer: { 
    position: 'relative', 
    borderRadius: '16px', 
    overflow: 'hidden', 
    boxShadow: '0 10px 30px rgba(0,0,0,0.2)', 
    background: '#000',
    minHeight: '480px'
  },
  video: { width: '100%', display: 'block' },
  overlayCanvas: { position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', pointerEvents: 'none' },

  statusBadge: {
    position: 'absolute',
    top: '20px',
    right: '20px',
    color: 'white',
    padding: '10px 20px',
    borderRadius: '9999px',
    fontWeight: 'bold',
    boxShadow: '0 4px 15px rgba(0,0,0,0.3)'
  },

  actions: { display: 'flex', gap: '14px', flexWrap: 'wrap', marginBottom: '30px' },
  btn: { 
    flex: 1, 
    padding: '16px', 
    border: 'none', 
    borderRadius: '12px', 
    color: 'white', 
    fontWeight: '600', 
    cursor: 'pointer', 
    fontSize: '1.02rem' 
  },
  btnPrimary: { 
    flex: 1, 
    padding: '16px', 
    backgroundColor: COLORS.primary, 
    border: 'none', 
    borderRadius: '12px', 
    color: 'white', 
    fontWeight: '600', 
    cursor: 'pointer', 
    fontSize: '1.02rem' 
  },
  btnDanger: { 
    flex: 1, 
    padding: '16px', 
    backgroundColor: '#475569', 
    border: 'none', 
    borderRadius: '12px', 
    color: 'white', 
    fontWeight: '600', 
    cursor: 'pointer', 
    fontSize: '1.02rem' 
  },

  comparisonContainer: { margin: '30px 0' },
  photoPair: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '25px' },
  photoLabel: { textAlign: 'center', marginBottom: '10px', fontWeight: '500', color: '#374151' },
  photo: { width: '100%', borderRadius: '12px', border: '3px solid #E2E8F0' },

  placeholder: {
    width: '100%',
    height: '300px',
    backgroundColor: '#F3F4F6',
    border: '3px dashed #9CA3AF',
    borderRadius: '12px',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    color: '#6B7280'
  },
  silhouette: { fontSize: '5.5rem', opacity: 0.5, marginBottom: '8px' },
  noCapture: {
    width: '100%',
    height: '300px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: '#F8FAFC',
    border: '3px dashed #CBD5E1',
    borderRadius: '12px',
    color: '#64748B',
    fontStyle: 'italic'
  },

  successBox: {
    animation: 'fadeIn 0.5s ease-out',
    background: '#F0FDF4',
    borderLeft: `6px solid ${COLORS.success}`,
    padding: '22px',
    borderRadius: '12px',
    margin: '25px 0'
  },
  errorBox: {
    animation: 'fadeIn 0.5s ease-out',
    background: '#FEF2F2',
    borderLeft: `6px solid ${COLORS.error}`,
    padding: '20px',
    borderRadius: '12px',
    color: '#991B1B',
    margin: '20px 0'
  },

  stats: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
    gap: '16px',
    margin: '30px 0',
    fontSize: '1.02rem'
  },

  debug: {
    background: '#F1F5F9',
    padding: '14px 18px',
    borderRadius: '10px',
    fontSize: '0.88rem',
    color: '#64748B',
    borderLeft: '5px solid #94A3B8'
  }
};

// Animation
const styleSheet = document.createElement('style');
styleSheet.textContent = `
  @keyframes fadeIn {
    from { opacity: 0; transform: translateY(15px); }
    to { opacity: 1; transform: translateY(0); }
  }
`;
document.head.appendChild(styleSheet);

export default CameraRecognition;
